// ===== 场景：后端返回订单列表，前端要做展示与统计 =====

const orders = [
  { id: 101, product: '机械键盘', price: 499,  quantity: 1, status: 'paid' },
  { id: 102, product: '显示器',   price: 1299, quantity: 2, status: 'pending' },
  { id: 103, product: '鼠标',     price: 199,  quantity: 3, status: 'paid' },
  { id: 104, product: '耳机',     price: 359,  quantity: 1, status: 'cancelled' },
];

// 1) filter：只保留已支付的订单（返回新数组，原数组不变）
const paidOrders = orders.filter((order) => order.status === 'paid');

// 2) map：把每条订单映射成视图需要的「小计」结构
const subtotals = paidOrders.map((order) => ({
  id: order.id,
  name: order.product,
  subtotal: order.price * order.quantity, // 箭头函数用 () 隐式返回对象
}));

// 3) reduce：把所有小计累加成总金额（注意 0 这个初始值！）
const totalAmount = subtotals.reduce(
  (sum, item) => sum + item.subtotal,
  0
);

console.log('已支付订单明细：', subtotals);
// [{ id: 101, name: '机械键盘', subtotal: 499 }, { id: 103, name: '鼠标', subtotal: 597 }]
console.log('总金额：', totalAmount); // 1096

// 4) 链式调用：一行完成「筛选 + 计算 + 汇总」
const total = orders
  .filter((o) => o.status === 'paid')
  .reduce((sum, o) => sum + o.price * o.quantity, 0);
console.log('链式写法总金额：', total); // 1096

// 5) reduce 进阶：按 status 分组（列表页「分组统计」超常用）
const grouped = orders.reduce((acc, order) => {
  const key = order.status;
  if (!acc[key]) acc[key] = [];   // 第一次遇到该分组，初始化为空数组
  acc[key].push(order);
  return acc;                     // 必须把累加器还回去
}, {});
console.log('按状态分组：', grouped);

// 6) 反例示范：map 忘记 return，会得到一堆 undefined
const wrong = orders.map((o) => {
  o.price * o.quantity; // 没有 return！
});
console.log('错误写法结果：', wrong); // [undefined, undefined, undefined, undefined]

